import RNA, random, sys
target = "......(......((((.....))))......)......................"
n = len(target)
# pair sets
pairs = []  # (i,j) 0-indexed target pairs
stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': pairs.append((stack.pop(), i))
pairpos = set()
for i,j in pairs: pairpos.add(i); pairpos.add(j)
print("pairs:",pairs, file=sys.stderr)

# complement map for random valid pair
def comp(b):
    return {'A':'U','U':'A','G':'C','C':'G'}[b]

wc = {('A','U'),('U','A'),('G','C'),('C','G'),('G','U'),('U','G')}

def fold(s):
    fc = RNA.fold_compound(s)
    fc.sc_parse_window_default()
    ss, mfe = fc.mfe()
    return ss, mfe

def bpdist(ss):
    return RNA.bp_distance(ss, target)

def randseq():
    s=['A']*n
    for i,j in pairs:
        b=random.choice(['G','C'])  # strong
        s[i]=b; s[j]=comp(b) if b in 'GC' else comp(b)
    # actually make them complementary properly
    for i,j in pairs:
        b=random.choice(['G','C','A','U'])
        s[i]=b; s[j]=comp(b)
    for p in range(n):
        if p not in pairpos:
            s[p]=random.choice('ACGU')
    return ''.join(s)

best=None
bestd=99
import time
t0=time.time()
random.seed(42)
# focused: keep pair positions complementary; mutate unpaired + occasionally pair identity
cur=randseq()
css,cmfe=fold(cur)
curd=bpdist(css)
bestd=curd; best=cur[:]
it=0
while time.time()-t0 < 90 and bestd>0:
    it+=1
    # mutate 1-3 positions
    cand=list(cur)
    for _ in range(random.randint(1,3)):
        p=random.randrange(n)
        if p in pairpos:
            # change pair identity: find partner
            for i,j in pairs:
                if p==i: 
                    b=random.choice('ACGU'); cand[i]=b; cand[j]=comp(b); break
                elif p==j:
                    b=random.choice('ACGU'); cand[j]=b; cand[i]=comp(b); break
        else:
            cand[p]=random.choice('ACGU')
    cand=''.join(cand)
    ss,mfe=fold(cand)
    d=bpdist(ss)
    # accept if better or with prob
    if d<curd or (d==curd and mfe<cmfe) or random.random()<0.02:
        cur=cand; css=ss; cmfe=mfe; curd=d
        if d<bestd:
            bestd=d; best=cur[:]
            print("iter",it,"bestd",bestd,"mfe",round(mfe,2), best, file=sys.stderr)
print("TOTAL iters",it,"bestd",bestd, file=sys.stderr)
print(best)
print("BESTD",bestd)
